(function (window) {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var todos = [];
  var filter = 'all';

  /**
   * @planks("the app is loaded cleanly")
   */
  function TodoApp() {
    this.loadTodos();
    this.bindEvents();
    this.render();
  }

  /**
   * @planks("localStorage has a key matching {string} with an entry for {string}")
   */
  TodoApp.prototype.save = function () {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  };

  /**
   * @planks("localStorage contains a todo {string}")
   * @planks("the app reloads")
   */
  TodoApp.prototype.loadTodos = function () {
    try {
      var stored = window.localStorage.getItem(STORAGE_KEY);
      todos = stored ? JSON.parse(stored) : [];
    } catch (e) {
      todos = [];
    }
  };

  /**
   * @planks-provisional("features/todo-management.feature:Todo ID generation produces unique identifiers")
   */
  TodoApp.prototype.generateId = function () {
    return Date.now() + Math.random();
  };

  /**
   * @planks("I type {string} into the new-todo input and press Enter")
   * @planks("I type {string} into the new-todo input and press Enter")
   */
  TodoApp.prototype.addTodo = function (title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      return false;
    }
    todos.push({
      id: this.generateId(),
      title: trimmed,
      completed: false
    });
    this.save();
    this.render();
    return true;
  };

  /**
   * @planks("I click the destroy button on the todo")
   * @planks("I double-click the label and clear the input and press Enter")
   */
  TodoApp.prototype.removeTodo = function (id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    this.save();
    this.render();
  };

  /**
   * @planks("I click the toggle checkbox on the todo")
   * @planks("I click the toggle checkbox on the todo")
   * @planks("I mark {string} as completed")
   */
  TodoApp.prototype.toggleTodo = function (id) {
    todos = todos.map(function (t) {
      if (t.id === id) {
        t.completed = !t.completed;
      }
      return t;
    });
    this.save();
    var todo = todos.find(function (t) { return t.id === id; });
    // Update DOM in-place to preserve element identity across the interaction,
    // unless the item would be hidden by the current filter.
    var todoList = document.querySelector('.todo-list');
    var li = todoList ? todoList.querySelector('li[data-id="' + id + '"]') : null;
    if (li) {
      // Check if the item is still visible under the current filter
      var stillVisible = (filter === 'all' ||
        (filter === 'active' && !todo.completed) ||
        (filter === 'completed' && todo.completed));
      if (stillVisible) {
        if (todo.completed) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        var checkbox = li.querySelector('.toggle');
        if (checkbox) {
          checkbox.checked = todo.completed;
        }
      } else {
        // Item is hidden by filter — remove its element from the DOM
        li.parentNode.removeChild(li);
      }
    }
    this.renderUI();
  };

  /**
   * @planks("I click the toggle-all checkbox")
   * @planks("I click the toggle-all checkbox")
   * @planks("I mark {string} as completed")
   */
  TodoApp.prototype.toggleAll = function (completed) {
    todos = todos.map(function (t) {
      t.completed = completed;
      return t;
    });
    this.save();
    // Update DOM in-place to preserve element identity
    var todoList = document.querySelector('.todo-list');
    if (todoList) {
      var items = todoList.querySelectorAll('li');
      Array.prototype.forEach.call(items, function (li) {
        if (completed) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        var checkbox = li.querySelector('.toggle');
        if (checkbox) {
          checkbox.checked = completed;
        }
      });
    }
    this.renderUI();
  };

  /**
   * @planks("I click the clear-completed button")
   */
  TodoApp.prototype.clearCompleted = function () {
    todos = todos.filter(function (t) { return !t.completed; });
    this.save();
    this.render();
  };

  /**
   * @planks("I double-click the label and change the value to {string} and press Enter")
   * @planks("I double-click the label and change the value to {string} and blur the input")
   * @planks("I double-click the label and clear the input and press Enter")
   */
  TodoApp.prototype.updateTodo = function (id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      this.removeTodo(id);
      return;
    }
    todos = todos.map(function (t) {
      if (t.id === id) {
        t.title = trimmed;
      }
      return t;
    });
    this.save();
    this.render();
  };

  /**
   * @planks("I click the {string} filter link")
   * @planks("I click the {string} filter link")
   */
  TodoApp.prototype.getFilteredTodos = function () {
    if (filter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (filter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  };

  /**
   * @planks-provisional("features/todo-management.feature:Active count and completed count sum to total")
   */
  TodoApp.prototype.getActiveCount = function () {
    return todos.filter(function (t) { return !t.completed; }).length;
  };

  /**
   * @planks-provisional("features/todo-management.feature:Active count and completed count sum to total")
   */
  TodoApp.prototype.getCompletedCount = function () {
    return todos.filter(function (t) { return t.completed; }).length;
  };

  /**
   * @planks("the app loads")
   * @planks("the app reloads")
   * @planks("the {string} filter is selected")
   */
  TodoApp.prototype.onHashChange = function (hash) {
    if (hash === '#/active') {
      filter = 'active';
    } else if (hash === '#/completed') {
      filter = 'completed';
    } else {
      filter = 'all';
    }
    this.render();
  };

  /**
   * @planks("the app is loaded cleanly")
   */
  TodoApp.prototype.bindEvents = function () {
    var self = this;

    // New todo input
    var newTodo = document.querySelector('.new-todo');
    if (newTodo) {
      newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
          self.addTodo(this.value);
          this.value = '';
        }
      });
    }

    // Toggle all
    var toggleAll = document.querySelector('#toggle-all');
    if (toggleAll) {
      toggleAll.addEventListener('change', function () {
        self.toggleAll(this.checked);
      });
    }

    // Clear completed
    var clearCompleted = document.querySelector('.clear-completed');
    if (clearCompleted) {
      clearCompleted.addEventListener('click', function () {
        self.clearCompleted();
      });
    }

    // Filter links
    var filterLinks = document.querySelectorAll('.filters a');
    Array.prototype.forEach.call(filterLinks, function (link) {
      link.addEventListener('click', function (e) {
        e.preventDefault();
        var href = this.getAttribute('href');
        window.location.hash = href;
        self.onHashChange(href);
      });
    });

    // Hash change
    window.addEventListener('hashchange', function () {
      self.onHashChange(window.location.hash);
    });

    // Todo list delegation
    var todoList = document.querySelector('.todo-list');
    if (todoList) {
      todoList.addEventListener('change', function (e) {
        var toggle = e.target.closest('.toggle');
        if (toggle) {
          var li = toggle.closest('li');
          if (li && li.dataset.id) {
            self.toggleTodo(Number(li.dataset.id));
          }
        }
      });

      todoList.addEventListener('click', function (e) {
        var destroy = e.target.closest('.destroy');
        if (destroy) {
          var li = destroy.closest('li');
          if (li && li.dataset.id) {
            self.removeTodo(Number(li.dataset.id));
          }
        }
      });

      todoList.addEventListener('dblclick', function (e) {
        var label = e.target.closest('label');
        if (label) {
          var li = label.closest('li');
          if (li) {
            li.classList.add('editing');
            var editInput = li.querySelector('.edit');
            if (editInput) {
              editInput.value = label.textContent.trim();
              editInput.focus();
            }
          }
        }
      });

      todoList.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
          var editInput = e.target.closest('.edit');
          if (editInput) {
            var li = editInput.closest('li');
            if (li && li.dataset.id) {
              self.updateTodo(Number(li.dataset.id), editInput.value);
            }
          }
        }
        if (e.keyCode === ESCAPE_KEY || e.key === 'Escape') {
          var editInput = e.target.closest('.edit');
          if (editInput) {
            var li = editInput.closest('li');
            if (li) {
              li.classList.remove('editing');
              var label = li.querySelector('label');
              if (label) {
                editInput.value = label.textContent.trim();
              }
            }
          }
        }
      });

      todoList.addEventListener('blur', function (e) {
        var editInput = e.target.closest('.edit');
        if (editInput) {
          var li = editInput.closest('li');
          if (li && li.dataset.id) {
            self.updateTodo(Number(li.dataset.id), editInput.value);
          }
        }
      }, true);
    }
  };

  /**
   * @planks("/^the ([#a-z]+) section is hidden$/")
   * @planks("/^the ([#a-z]+) section is visible$/")
   * @planks("the todo-count shows {string}")
   * Update all UI except the todo list itself. Used by in-place
   * mutations that must preserve element identity.
   */
  TodoApp.prototype.renderUI = function () {
    var main = document.querySelector('#main');
    var footer = document.querySelector('#footer');
    var todoCount = document.querySelector('.todo-count');
    var clearBtn = document.querySelector('.clear-completed');
    var toggleAll = document.querySelector('#toggle-all');
    var activeCount = this.getActiveCount();
    var completedCount = this.getCompletedCount();

    // Show/hide main and footer
    if (main) {
      main.style.display = todos.length === 0 ? 'none' : '';
    }
    if (footer) {
      footer.style.display = todos.length === 0 ? 'none' : '';
    }

    // Update count
    if (todoCount) {
      var itemWord = activeCount === 1 ? 'item' : 'items';
      todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';
    }

    // Show/hide clear completed
    if (clearBtn) {
      clearBtn.style.display = completedCount === 0 ? 'none' : '';
    }

    // Update toggle all
    if (toggleAll) {
      toggleAll.checked = todos.length > 0 && activeCount === 0;
    }

    // Update filter links
    var filterLinks = document.querySelectorAll('.filters a');
    Array.prototype.forEach.call(filterLinks, function (link) {
      link.classList.remove('selected');
      var href = link.getAttribute('href');
      if ((filter === 'all' && (href === '#/' || href === '#')) ||
          (filter === 'active' && href === '#/active') ||
          (filter === 'completed' && href === '#/completed')) {
        link.classList.add('selected');
      }
    });
  };

  /**
   * @planks-provisional("features/todo-management.feature:The todo list is re-rendered from scratch after add")
   */
  TodoApp.prototype.render = function () {
    var self = this;
    var filteredTodos = this.getFilteredTodos();
    var todoList = document.querySelector('.todo-list');

    // Rebuild the todo list from scratch
    if (todoList) {
      todoList.innerHTML = '';
      filteredTodos.forEach(function (todo) {
        var li = document.createElement('li');
        li.dataset.id = todo.id;
        if (todo.completed) {
          li.classList.add('completed');
        }
        li.innerHTML =
          '<div class="view">' +
            '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
            '<label>' + self.escapeHtml(todo.title) + '</label>' +
            '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';
        todoList.appendChild(li);
      });
    }

    this.renderUI();
  };

  /**
   * @planks-provisional("features/todo-management.feature:HTML content is escaped in todo titles")
   */
  TodoApp.prototype.escapeHtml = function (text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  };

  window.app = new TodoApp();

})(window);

